{"content": "def should_retry(status, error):
    # Retry status 429 and all 5xx; never retry other 4xx
    if status is not None:
        if status == 429:
            return True
        if 500 <= status < 600:
            return True
        return False

    # When status is None, retry only error values timeout or connection
    if error in ('timeout', 'connection'):
        return True

    # Unknown errors must be false
    return False
